def transform(grid):
    g=[row[:] for row in grid]
    # overwrite known rectangular colored panels; all other anomalous marks are background 8
    patches=[(0,1,10,13,6),(4,6,7,12,0),(8,11,4,9,0),(13,15,4,7,7),(15,18,10,14,9),(20,24,1,6,6),(21,25,10,14,7),(26,28,1,3,9)]
    # panels contain colors differing from surrounding background and retain full rectangular extent
    for r0,r1,c0,c1,col in patches:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): g[r][c]=col
    # isolated marker/noise cells are background, except part of small 7 shape at upper left
    for r in range(len(g)):
